BEGIN;
SELECT no_plan();
INSERT INTO auth.users(id,email,raw_app_meta_data) VALUES('13500000-0000-4000-8000-000000000001','order-owner@example.test','{"_invite_provisioned":true}'),('13500000-0000-4000-8000-000000000002','order-foreign@example.test','{"_invite_provisioned":true}');
CREATE TEMP TABLE orders_fixture(kind text PRIMARY KEY,tenant_id uuid);
INSERT INTO orders_fixture VALUES('own',(public.provision_company_atomic('13500000-0000-4000-8000-000000000001','{"name":"Order owner fixture","domain":"orders-own.example.test","slug":"orders-own-fixture"}')->>'id')::uuid),('foreign',(public.provision_company_atomic('13500000-0000-4000-8000-000000000002','{"name":"Order foreign fixture","domain":"orders-foreign.example.test","slug":"orders-foreign-fixture"}')->>'id')::uuid);
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
UPDATE public.users SET must_change_password=false WHERE auth_user_id IN('13500000-0000-4000-8000-000000000001','13500000-0000-4000-8000-000000000002');
INSERT INTO public.drivers(id,tenant_id,full_name_ar,full_name_en,primary_mobile,category,status) SELECT CASE kind WHEN 'own' THEN '13500000-0000-4000-8000-000000000011'::uuid ELSE '13500000-0000-4000-8000-000000000012'::uuid END,tenant_id,'Order fixture',CASE kind WHEN 'own' THEN 'Search beyond page' ELSE 'Foreign driver' END,'0501350001','freelancer','active' FROM orders_fixture;
INSERT INTO public.delivery_platforms(id,tenant_id,code,name_ar,name_en) SELECT CASE kind WHEN 'own' THEN '13500000-0000-4000-8000-000000000021'::uuid ELSE '13500000-0000-4000-8000-000000000022'::uuid END,tenant_id,'FIXTURE','Order platform','Platform history fixture' FROM orders_fixture;
CREATE TEMP TABLE order_result(result jsonb,input jsonb);
INSERT INTO order_result(input) VALUES('{"driver_id":"13500000-0000-4000-8000-000000000011","platform_id":"13500000-0000-4000-8000-000000000021","entry_date":"2098-11-15","orders_delivered":17,"gross_revenue":25.50}');
GRANT ALL ON orders_fixture,order_result TO authenticated;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13500000-0000-4000-8000-000000000001","aal":"aal2"}',true);
UPDATE order_result SET result=public.save_order_entry(input||'{"tenant_id":"13500000-0000-4000-8000-000000000022"}');
SELECT ok((SELECT result->>'id' IS NOT NULL FROM order_result),'empty tenant can create manual order');
SELECT is((SELECT tenant_id FROM public.daily_order_entries WHERE id=(SELECT (result->>'id')::uuid FROM order_result)),(SELECT tenant_id FROM orders_fixture WHERE kind='own'),'caller ownership cannot be overridden');
SELECT throws_ok($$SELECT public.save_order_entry(input||'{"driver_id":"13500000-0000-4000-8000-000000000012"}') FROM order_result$$,'P0001','ORDER_TENANT_DRIVER_REQUIRED','foreign driver rejected');
SELECT throws_ok($$SELECT public.save_order_entry(input||'{"platform_id":"13500000-0000-4000-8000-000000000022"}') FROM order_result$$,'P0001','ORDER_ACTIVE_TENANT_PLATFORM_REQUIRED','foreign platform rejected');
SELECT throws_ok($$SELECT public.save_order_entry(input||'{"orders_failed":1.5}') FROM order_result$$,'P0001','ORDER_INVALID_COUNT','fractional count rejected');
SELECT throws_ok($$SELECT public.save_order_entry(input||'{"gross_revenue":1.001}') FROM order_result$$,'P0001','ORDER_INVALID_AMOUNT','unrounded money rejected');
SELECT throws_ok($$SELECT public.save_order_entry(input||'{"is_locked":true}') FROM order_result$$,'P0001','ORDER_LOCK_REQUIRES_PREPARATION','manual locks cannot bypass preparation');
SELECT throws_ok($$SELECT public.save_order_entry(input,(result->>'id')::uuid,'2000-01-01') FROM order_result$$,'P0001','ORDER_STALE_VERSION','stale edit rejected');
UPDATE order_result SET result=public.save_order_entry(input||'{"orders_delivered":19,"notes":"Corrected source"}',(result->>'id')::uuid,(result->>'updated_at')::timestamptz);
SELECT is((SELECT orders_delivered FROM public.daily_order_entries WHERE id=(SELECT (result->>'id')::uuid FROM order_result)),19,'edit persists corrected count');
SELECT throws_ok($$UPDATE public.daily_order_entries SET orders_delivered=999 WHERE id=(SELECT (result->>'id')::uuid FROM order_result)$$,'42501',NULL,'direct API cannot bypass atomic write boundary');
SELECT throws_ok($$SELECT public.archive_order_entry((result->>'id')::uuid,'2000-01-01') FROM order_result$$,'P0001','ORDER_STALE_VERSION','stale archive rejected');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13500000-0000-4000-8000-000000000002","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.archive_order_entry((result->>'id')::uuid,(result->>'updated_at')::timestamptz) FROM order_result$$,'P0001','ORDER_NOT_FOUND','foreign tenant cannot archive known row');
SELECT is(public.list_order_entries('2098-11')->>'total','0','foreign tenant list excludes source records');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13500000-0000-4000-8000-000000000001","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.list_order_entries('2098-11')$$,'P0001','AUTH007: platform operation permission required','unverified MFA cannot read privileged order report');
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13500000-0000-4000-8000-000000000001","aal":"aal2"}',true);
SELECT lives_ok($$SELECT public.archive_order_entry((result->>'id')::uuid,(result->>'updated_at')::timestamptz) FROM order_result$$,'archive succeeds without deleting history');
RESET ROLE;
SELECT ok((SELECT deleted_at IS NOT NULL FROM public.daily_order_entries WHERE id=(SELECT (result->>'id')::uuid FROM order_result)),'archive retains original record');
INSERT INTO public.daily_order_entries(tenant_id,driver_id,platform_id,entry_date,shift_label,orders_delivered,orders_failed,gross_revenue) SELECT tenant_id,'13500000-0000-4000-8000-000000000011','13500000-0000-4000-8000-000000000021','2098-11-15','bulk-'||n,2,1,3.25 FROM orders_fixture CROSS JOIN generate_series(1,1101)n WHERE kind='own';
SET LOCAL ROLE authenticated;
SELECT is(public.list_order_entries('2098-11')->>'total','1101','count covers more than API row cap');
SELECT is(jsonb_array_length(public.list_order_entries('2098-11','','1',50)->'rows'),50,'default page is bounded');
SELECT is(jsonb_array_length(public.list_order_entries('2098-11','',23,50)->'rows'),1,'last page reaches record beyond old limit');
SELECT is(public.list_order_entries('2098-11')->'summary'->>'delivered','2202','aggregate includes all1101 rows');
SELECT is(public.list_order_entries('2098-11')->'summary'->>'revenue','3578.25','exact revenue aggregate covers complete period');
SELECT is(public.list_order_entries('2098-11','Search beyond page')->>'total','1101','server search is independent of current page');
SELECT is(jsonb_array_length(public.export_order_entries('2098-11')),1101,'single snapshot order export includes all1101 rows');
SELECT throws_ok($$SELECT public.list_order_entries('2098-99')$$,'P0001','ORDER_INVALID_PAGE','invalid period rejected');
RESET ROLE;
CREATE TEMP TABLE platform_results(result jsonb,payment jsonb);
INSERT INTO platform_results DEFAULT VALUES;
GRANT ALL ON platform_results TO authenticated;
SET LOCAL ROLE authenticated;
UPDATE platform_results SET result=public.save_delivery_platform('{"code":"ATOMIC_NEW","name_ar":"New atomic platform","rate_type":"flat","rate_per_order":2.25,"sort_order":0}');
SELECT ok((SELECT result->>'id' IS NOT NULL FROM platform_results),'platform creates with atomic master audit');
SELECT throws_ok($$SELECT public.save_delivery_platform('{"code":"ATOMIC_NEW","name_ar":"Changed","rate_type":"flat"}',(result->>'id')::uuid,'2000-01-01') FROM platform_results$$,'P0001','PLATFORM_STALE_VERSION','stale platform edit rejected');
UPDATE platform_results SET result=public.save_delivery_platform('{"code":"ATOMIC_NEW","name_ar":"Edited platform","rate_type":"flat","rate_per_order":3.50,"is_active":true}',(result->>'id')::uuid,(result->>'updated_at')::timestamptz);
SELECT is((SELECT name_ar FROM public.delivery_platforms WHERE id=(SELECT (result->>'id')::uuid FROM platform_results)),'Edited platform','platform edit persisted');
SELECT throws_ok($$UPDATE public.delivery_platforms SET name_ar='Bypass' WHERE id=(SELECT (result->>'id')::uuid FROM platform_results)$$,'42501',NULL,'direct platform write bypass denied');
SELECT throws_ok($$SELECT public.save_delivery_platform('{}','13500000-0000-4000-8000-000000000022',now(),true)$$,'P0001','PLATFORM_NOT_FOUND','foreign platform deactivation rejected');
UPDATE platform_results SET result=public.save_delivery_platform('{}',(result->>'id')::uuid,(result->>'updated_at')::timestamptz,true);
SELECT is((SELECT is_active FROM public.delivery_platforms WHERE id=(SELECT (result->>'id')::uuid FROM platform_results)),false,'deactivation marks master inactive');
SELECT ok((SELECT deleted_at IS NULL FROM public.delivery_platforms WHERE id=(SELECT (result->>'id')::uuid FROM platform_results)),'deactivation retains accessible history master');
SELECT is(public.list_delivery_platforms('Edited platform')->>'total','1','inactive master remains searchable');
SELECT throws_ok($$SELECT public.save_order_entry(input||jsonb_build_object('platform_id',(SELECT result->>'id' FROM platform_results))) FROM order_result$$,'P0001','ORDER_ACTIVE_TENANT_PLATFORM_REQUIRED','new entries cannot use inactive platform');
UPDATE platform_results SET payment=public.save_platform_payment(jsonb_build_object('platform_id',result->>'id','period_year',2098,'period_month',11,'expected_amount',150,'received_amount',25,'payment_date','2098-11-16','payment_ref','RECEIPT-FIXTURE'));
SELECT is((SELECT outstanding_amount::text FROM public.platform_payments WHERE id=(SELECT (payment->>'id')::uuid FROM platform_results)),'125.00','inactive platform history can be reconciled with exact outstanding amount');
SELECT throws_ok($$SELECT public.save_platform_payment(jsonb_build_object('platform_id',result->>'id','period_year',2098,'period_month',11,'expected_amount',150,'received_amount',25,'payment_date','2098-11-16')) FROM platform_results$$,'P0001','PLATFORM_PAYMENT_EXISTS_OR_CHANGED: open the existing period before correcting it','blank new form cannot overwrite existing payment period');
UPDATE platform_results SET payment=public.save_platform_payment(jsonb_build_object('platform_id',result->>'id','period_year',2098,'period_month',11,'expected_amount',150,'received_amount',150,'payment_date','2098-11-17','expected_updated_at',payment->>'updated_at'));
SELECT is((SELECT payment_status::text FROM public.platform_payments WHERE id=(SELECT (payment->>'id')::uuid FROM platform_results)),'paid','versioned payment correction atomically updates state');
SELECT throws_ok($$SELECT public.save_platform_payment(jsonb_build_object('platform_id',result->>'id','period_year',2098,'period_month',12,'expected_amount',150,'received_amount',151,'payment_date','2098-12-17')) FROM platform_results$$,'P0001','PLATFORM_PAYMENT_INVALID_AMOUNT','overpayment cannot create negative outstanding');
SELECT throws_ok($$SELECT public.save_platform_payment(jsonb_build_object('platform_id',result->>'id','period_year',2098,'period_month',12,'expected_amount',150,'received_amount',10)) FROM platform_results$$,'P0001','PLATFORM_PAYMENT_DATE_REQUIRED','received funds require date');
SELECT is(public.get_delivery_platform_detail('13500000-0000-4000-8000-000000000021','daily','2098-11')->'rows'->0->>'orders_delivered','2202','daily detail aggregates all source entries beyond row caps');
SELECT is(jsonb_array_length(public.export_delivery_platform_data('13500000-0000-4000-8000-000000000021','2098-11')->'entries'),1101,'single snapshot export includes complete platform source entries');
RESET ROLE;
INSERT INTO public.monthly_driver_orders(tenant_id,driver_id,platform_id,period_year,period_month,total_delivered) SELECT tenant_id,'13500000-0000-4000-8000-000000000011','13500000-0000-4000-8000-000000000021',extract(year FROM date '2000-01-01'+(n||' month')::interval),extract(month FROM date '2000-01-01'+(n||' month')::interval),2 FROM orders_fixture CROSS JOIN generate_series(0,600)n WHERE kind='own';
SET LOCAL ROLE authenticated;
SELECT is(public.get_delivery_platform_detail('13500000-0000-4000-8000-000000000021','monthly','2098-11')->>'total','601','monthly aggregate reaches beyond previous500 limit');
SELECT is(jsonb_array_length(public.get_delivery_platform_detail('13500000-0000-4000-8000-000000000021','monthly','2098-11',13,50)->'rows'),1,'monthly last page remains accessible');
RESET ROLE;
INSERT INTO public.attendance_periods(tenant_id,period_year,period_month,start_date,end_date,status) SELECT tenant_id,2098,11,'2098-11-01','2098-11-30','locked' FROM orders_fixture WHERE kind='own';
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.save_order_entry(input||'{"shift_label":"locked-new"}') FROM order_result$$,'P0001','PAY_PREPARATION_LOCKED','period lock rejects new entries even without UI checks');
SELECT throws_ok($$SELECT public.archive_order_entry(id,updated_at) FROM public.daily_order_entries WHERE tenant_id=(SELECT tenant_id FROM orders_fixture WHERE kind='own') AND deleted_at IS NULL LIMIT 1$$,'P0001','PAY_PREPARATION_LOCKED','period lock rejects source archival');
RESET ROLE;
SET LOCAL ROLE service_role;
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
SELECT throws_ok($$UPDATE public.daily_order_entries SET orders_delivered=999 WHERE id=(SELECT id FROM public.daily_order_entries WHERE entry_date='2098-11-15' AND driver_id='13500000-0000-4000-8000-000000000011' AND deleted_at IS NULL LIMIT 1)$$,'P0001','PAY_PREPARATION_LOCKED','BYPASSRLS service ingestion cannot modify a locked period');
RESET ROLE;
SELECT set_config('request.jwt.claims','{"role":"authenticated","sub":"13500000-0000-4000-8000-000000000001","aal":"aal2"}',true);
CREATE FUNCTION pg_temp.reject_order_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.action='order_entry_created' THEN RAISE EXCEPTION 'order audit fault'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER order_test_audit BEFORE INSERT ON public.audit_log FOR EACH ROW EXECUTE FUNCTION pg_temp.reject_order_audit();
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.save_order_entry(input||'{"entry_date":"2098-12-01"}') FROM order_result$$,'P0001','order audit fault','audit failure aborts source write');
RESET ROLE;
SELECT is((SELECT count(*)::integer FROM public.daily_order_entries WHERE tenant_id=(SELECT tenant_id FROM orders_fixture WHERE kind='own') AND entry_date='2098-12-01'),0,'no partial order after audit failure');
SET LOCAL ROLE anon;
SELECT throws_ok($$SELECT public.list_order_entries('2098-11')$$,'42501',NULL,'anonymous cannot execute reporting RPC');
RESET ROLE;
SELECT * FROM finish();
ROLLBACK;
